export const CATEGORY_CHASSIS: readonly RefChassis[] = [{"category":"HQ/Governance","outputFormula":"—","mechanics":"Gates every other building's level. Grants queue slots, command radius, plot count, policy/doctrine slots. Its destruction caps the whole settlement.","scaling":"+2 plots, +1 queue per 4 grades, +radius","vulnerability":"Siege priority target; loss cascades to every building"},{"category":"Extraction","outputFormula":"base × LevelCurve × tile richness × staffing%","mechanics":"Produces raw resources into a local stockpile that raiders can plunder. Tile richness is fixed by map position. Depletion does not exist — but hazard tiles impose attrition on workers.","scaling":"Output (L+1)^1.12","vulnerability":"Raiding the stockpile; worker loss; tile capture"},{"category":"Processing","outputFormula":"min(input supply, throughput) × conversion rate","mechanics":"Converts inputs to outputs. Throughput caps how much it can handle per tick; conversion rate improves with level. Idle without inputs regardless of level.","scaling":"Throughput and conversion both rise","vulnerability":"Supply-line interdiction — starve the inputs"},{"category":"Military","outputFormula":"—","mechanics":"Grants unit queue slots, gates unit archetypes and grade tiers, reduces training time by a bounded percentage. Parallel lines from Factory tier onward.","scaling":"+queue slots, −train time (capped −40%)","vulnerability":"Raided mid-production: partial units are destroyed"},{"category":"Defense","outputFormula":"defense multiplier + flat garrison HP","mechanics":"Multiplies defending units' defense pool, adds wall HP that must be breached, projects zone of control onto adjacent roads/lanes. Must be reduced by siege before plunder.","scaling":"Multiplier and HP both rise","vulnerability":"Siege engines; sappers; bombardment; Heaven's Envy debuff"},{"category":"Knowledge","outputFormula":"research points or intel radius","mechanics":"Generates research, extends intel range, hosts agent operations, recruits Great People. Intel buildings reveal incoming attacks earlier.","scaling":"Rate and radius rise","vulnerability":"Sabotage; counter-intel raids; tech theft targets"},{"category":"Trade","outputFormula":"Coin/hour + route slots + market depth","mechanics":"Generates Coin, grants standing trade route slots, deepens local market order books, collects tolls on routes crossing your zone of control.","scaling":"+routes, +Coin, +depth","vulnerability":"Blockade; piracy on the routes it spawns"},{"category":"Culture","outputFormula":"Culture/hour + happiness","mechanics":"Raises happiness (productivity multiplier, revolt suppression), generates Culture that exerts border pressure on adjacent low-culture plots, and hosts festivals and ideology projection.","scaling":"Culture and happiness rise","vulnerability":"Slow to rebuild; razing it is a favourite spite target"},{"category":"Logistics","outputFormula":"storage cap / movement / supply range","mechanics":"Raises stockpile caps, extends army supply range, speeds movement along owned infrastructure, enables hauling volume.","scaling":"Caps and ranges rise","vulnerability":"Chokepoint capture; convoy raiding"},{"category":"Special","outputFormula":"unique","mechanics":"One-off gated effects: Ascension Projects, colony founding, terraforming, megastructures, wonder-class effects. Usually Monumental, usually announced publicly when begun.","scaling":"Varies per building","vulnerability":"Publicly announced; attractive sabotage target"},{"category":"Cultivation","outputFormula":"Qi/hour + realm & technique unlocks","mechanics":"Generates Qi, hosts breakthroughs and tribulations, unlocks techniques, refines pills, tames spirit beasts. Fully resets on capture — cultivation infrastructure is bound to its builder.","scaling":"Qi rate and slot count rise","vulnerability":"Cannot be captured usefully; tribulation-crashing raids"}];

